// data/contact-glue.js
var wired = false;
function wireContact(store2) {
  if (wired) return;
  wired = true;
  store2.subscribe("ctSubmit", async (payload) => {
    if (!payload || !payload.email) return;
    store2.setValue("ctError", "");
    try {
      const res = await fetch("/swc/contact", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(payload)
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
      store2.setValue("ctSent", true);
    } catch {
      store2.setValue("ctError", "failed");
    }
  });
}
__name(wireContact, "wireContact");

